<?php $pageTitle='Rekap Registrasi'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Manajemen','Administrator SIMRS']);$total=(int)$pdo->query("SELECT COUNT(*) FROM patients")->fetchColumn();$visits=(int)$pdo->query("SELECT COUNT(*) FROM visits")->fetchColumn();$today=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(created_at)=CURDATE()")->fetchColumn();$appt=(int)$pdo->query("SELECT COUNT(*) FROM appointments")->fetchColumn();$bpjs=(int)$pdo->query("SELECT COUNT(*) FROM insurance_verifications WHERE payer='BPJS' AND status='AKTIF'")->fetchColumn();$dups=(int)$pdo->query("SELECT COUNT(*) FROM patients WHERE duplicate_flag=1")->fetchColumn();$clinic=$pdo->query("SELECT clinic,COUNT(*) total FROM visits GROUP BY clinic ORDER BY total DESC")->fetchAll();$status=$pdo->query("SELECT status,COUNT(*) total FROM visits GROUP BY status ORDER BY total DESC")->fetchAll();include 'partials/header.php'; ?>
